{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C30"],
      "claim": "Betaxolol, a basic aryloxypropanolamine with an aromatic ether and hydroxyl, had absolute oral bioavailability 87.5±7.9% in healthy subjects, directly supporting F≥20% for a similarly functionalized basic molecule.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Veralipride, a basic substituted benzamide with a pyrrolidine amine and multiple polar groups, showed absolute oral bioavailability 78.6±20.2%, supporting high F for a polar basic drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Brigatinib, a large heteroaromatic basic molecule with multiple polar substituents, had oral bioavailability ~46% in healthy volunteers, supporting F≥20% for a complex functionalized amine.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Omeprazole, a methoxy-substituted heteroaromatic with a basic benzimidazole, had absolute oral bioavailability 56±7% in young volunteers, supporting high F for a methoxyheteroaromatic basic compound.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Abecarnil, a lipophilic heteroaromatic ester, had absolute oral bioavailability 39±17% in healthy volunteers, supporting F≥20% despite substantial first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Encainide, a basic amide with methoxy and cyclic amine groups, had absolute oral bioavailability 32±7% in normal subjects, supporting F≥20% for a basic, metabolically cleared drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Nabumetone's active metabolite had absolute oral bioavailability 38% in healthy subjects, supporting F≥20% for a lipophilic methoxynaphthalene ketone.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues show absolute oral bioavailability at or above 20%, with most values between 30% and 89%; no affirmative evidence supports F<20%. The query's basic bicyclic amine, secondary alcohol, and methoxyquinoline are consistent with these high-F compounds, so F≥20% is strongly supported.",
  "evidence_gaps": [
    "No direct human absolute bioavailability measurement for the query molecule.",
    "First-pass metabolic stability of the vinyl and benzylic alcohol moieties is not directly measured.",
    "Encainide shows wide interindividual bioavailability variability (7-82%), but its mean and most reported values remain ≥20%."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

